    LANGUAGE_WRAPPER = 'In a math contest, a sequence {a_n} of positive real numbers is defined by the parameters p={p}, s={s}, t={t}, and a rational m={m_frac} with 0<m<1. The initial values are a_1={a1} and a_2={a2}. For all n>=1, the sequence satisfies the nonlinear second-order recurrence:\n\n(s + t a_{n+2})^{p^2} = {m_frac} (s + t a_{n+1})^{p} + (1 - {m_frac}) (s + t a_n).\n\nFind a closed-form expression for a_n in terms of n, and then output your final answer exactly in the format:\n### The final answer is: \\boxed{<your answer>}\nYour final answer must be a formula containing n and should be as precise as possible.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# Choose p >= 3 to enforce nontrivial nested roots
p = rng.randint(3, 6)
# Choose s,t positive integers
s = rng.randint(1, 5)
t = rng.randint(1, 5)
# Choose k >= 2 and ensure k > s so that a2 = (k - s)/t > 0
k = rng.randint(2, 7)
if k <= s:
    k = rng.randint(s+1, s+6)
# Construct y1 = k^p so that y2 = k, giving exact pth-root structure
y1 = k ** p
# Compute a1 = (y1 - s)/t and a2 = (k - s)/t as reduced fractions
def frac_str(num, den):
    g = math.gcd(num, den)
    num //= g
    den //= g
    if den == 1:
        return str(num)
    return f"{num}/{den}"
a1_str = frac_str(y1 - s, t)
a2_str = frac_str(k - s, t)
# Choose m as M/(M+N), 0<m<1, simple small integers
M = rng.randint(1, 5)
N = rng.randint(1, 5)
while M <= 0 or N <= 0:
    M = rng.randint(1, 5)
    N = rng.randint(1, 5)
m_num = M
m_den_total = M + N
m_frac = f"{M}/{M+N}"
return {
    'p': p,
    's': s,
    't': t,
    'a1': a1_str,
    'a2': a2_str,
    'm_frac': m_frac,
    'm_num': m_num,
    'm_den_total': m_den_total
}

