    return (False, None)
# Basic difficulty constraints
if p < 3:
    # Enforce nontrivial nested root structure
    return (False, None)
if m_num <= 0 or m_den_total <= m_num:
    # Enforce 0 < m < 1
    return (False, None)
# Parse fractions exactly
from fractions import Fraction
def parse_frac_str(s):
    s = str(s).strip()
    if '/' in s:
