a1 = parse_frac_str(a1_str)
a2 = parse_frac_str(a2_str)
# Positivity check
if a1 <= 0 or a2 <= 0 or s <= 0 or t <= 0:
    return (False, None)
# Construct y1 and y2 and check the designed root relation holds: y2^p = y1
y1 = Fraction(s) + Fraction(t) * a1
y2 = Fraction(s) + Fraction(t) * a2
if y2 ** p != y1:
    # The instance does not satisfy the intended structure
    return (False, None)
# Build the closed-form answer string.
# a_n = ((s + t a_1)^{1/(p^{n-1})} - s) / t
# Use LaTeX with explicit constants to avoid ambiguity.
ans = f"### The final answer is: \\boxed{{\\frac{{\\left({s}+{t}\\cdot({a1_str})\\right)^{{\\frac{{1}}{{{p}^{{n-1}}}}}} - {s}}}{{{t}}}}}"
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

